public struct SandWidget: Codable, Sendable, Equatable {
	public let allowCustom: Bool?
	public let copyKind: SandWidgetCopyKind?
	public let dismissOnMoveOn: Bool?
	public let helpText: String?
	public let multiSelect: Bool?
	public let options: [SandChoiceOption]
	public let prompt: String
	public init(allowCustom: Bool? = nil, copyKind: SandWidgetCopyKind? = nil, dismissOnMoveOn: Bool? = nil, helpText: String? = nil, multiSelect: Bool? = nil, options: [SandChoiceOption], prompt: String) {
		self.allowCustom = allowCustom
		self.copyKind = copyKind
		self.dismissOnMoveOn = dismissOnMoveOn
		self.helpText = helpText
		self.multiSelect = multiSelect
		self.options = options
		self.prompt = prompt
	}
	enum CodingKeys: String, CodingKey {
		case allowCustom, copyKind, dismissOnMoveOn, helpText, multiSelect, options, prompt
	}
	public func encode(to encoder: Encoder) throws {
		var container = encoder.container(keyedBy: CodingKeys.self)
		try container.encodeIfPresent(allowCustom, forKey: .allowCustom)
		try container.encodeIfPresent(copyKind, forKey: .copyKind)
		try container.encodeIfPresent(dismissOnMoveOn, forKey: .dismissOnMoveOn)
		try container.encodeIfPresent(helpText, forKey: .helpText)
		try container.encodeIfPresent(multiSelect, forKey: .multiSelect)
		try container.encode(options, forKey: .options)
		try container.encode(prompt, forKey: .prompt)
	}
}

